import {FishingGame,FISH,RODS} from './fishing-engine.js';
import {loadWords} from './word-store.js';
import {readWords} from './vocab.js';
import {partyFX} from './party-fx.js';
import {bindGameLifecycle} from './game-lifecycle.js';
const $=id=>document.getElementById(id),sections=['intro','select','quiz','cast','fight','correction','reveal','result'];
let game=null,previous=0,pointer=null,muted=true,audio=null,book={},best=0,sceneTimer=0,effectTimer=0,payoutStart=0,payoutTotal=0,now=0;
try{const b=JSON.parse(localStorage.getItem('party-fish-book-v1')||'{}');if(b&&typeof b==='object'&&!Array.isArray(b))book=b;best=Math.max(0,Number(localStorage.getItem('party-fish-best-v2'))||0);}catch{}
function sound(kind='hit'){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=kind==='catch'?[523,659,784,1047,1319]:kind==='boss'?[110,147,165,220]:kind==='special'?[220,440,880,1320]:kind==='miss'?[330,220]:[659,988];notes.forEach((hz,i)=>{const o=audio.createOscillator(),v=audio.createGain(),t=audio.currentTime+i*.095;o.type=kind==='boss'?'sawtooth':'triangle';o.frequency.setValueAtTime(hz,t);v.gain.setValueAtTime(0,t);v.gain.linearRampToValueAtTime(.065,t+.015);v.gain.exponentialRampToValueAtTime(.001,t+.22);o.connect(v);v.connect(audio.destination);o.start(t);o.stop(t+.23);});}catch{}}
$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'音 OFF':'音 ON';$('sound').setAttribute('aria-pressed',String(!muted));if(!muted)sound();};
function sprite(el,id){el.style.setProperty('--col',id%3);el.style.setProperty('--row',Math.floor(id/3));}
function collection(){const list=$('collection');list.replaceChildren();let n=0;for(const f of FISH){const size=Number(book[f.name])||0,article=document.createElement('article'),art=document.createElement('span'),name=document.createElement('strong'),record=document.createElement('p');art.className='sprite'+(size?'':' locked');art.setAttribute('aria-hidden','true');sprite(art,f.id);name.textContent=size?f.name:'？？？';record.textContent=size?size+' cm':'未発見';article.append(art,name,record);list.append(article);if(size)n++;}$('bookCount').textContent=n+' / 6';}
function show(id){for(const s of sections)$(s).hidden=s!==id;}
function clearInput(){pointer=null;game?.hold(false);$('reel').textContent='長押しで巻く';}
function clearEffects(){clearTimeout(sceneTimer);clearTimeout(effectTimer);$('cutin').classList.remove('show');$('strike').classList.remove('show');$('coins').replaceChildren();}
function cutin(text){clearTimeout(sceneTimer);const el=$('cutin');el.textContent=text;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');sceneTimer=setTimeout(()=>el.classList.remove('show'),1600);}
function sparkle(){clearTimeout(effectTimer);$('strike').classList.remove('show');void $('strike').offsetWidth;$('strike').classList.add('show');effectTimer=setTimeout(()=>{$('strike').classList.remove('show');$('coins').replaceChildren();},2200);}
function coins(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;$('coins').replaceChildren();for(let i=0;i<22;i++){const el=document.createElement('span');el.className='coin';el.textContent='★';el.style.setProperty('--dx',((i%11)-5)*26+'px');el.style.setProperty('--delay',Math.floor(i/11)*.15+(i%3)*.04+'s');$('coins').append(el);}sparkle();}
function pause(value){if(!game||game.phase==='done')return;clearInput();game.pause(value);$('pauseScreen').hidden=!value;if(value){clearEffects();partyFX.clear();$('resume').focus();}else if(game.phase==='reel')$('reel').focus();}
bindGameLifecycle(window,document,{clearInput,pause});$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);
function hud(){$('round').textContent=game.round+' / 8 投';$('score').textContent='★ '+game.score;$('energy').textContent='◆ '.repeat(game.energy)+'◇ '.repeat(3-game.energy);$('chain').textContent=game.fever?'★ 報酬2倍':'● '.repeat(game.chain)+'○ '.repeat(3-game.chain);$('feverLabel').textContent=game.fever?'フィーバー中！':game.feverLeft?'次から2投フィーバー':'3連続でフィーバー';$('specialCount').textContent=game.energy+' / 3';$('special').disabled=game.phase!=='reel'||game.energy<1||game.cooldown>0||game.paused;$('missions').textContent=[['three','3匹キャッチ ★50'],['cast','パーフェクト投げ3回 ★50'],['boss','伝説キャッチ ★100']].map(([key,s])=>(game.missions.has(key)?'✓ ':'□ ')+s).join(' ／ ');}
function begin(){const pack=readWords(loadWords());try{if(pack.errors.length)throw Error(pack.errors[0]);game=new FishingGame(pack.entries);}catch(e){$('error').textContent=e.message;return;}clearInput();clearEffects();$('pauseScreen').hidden=true;partyFX.resetRewards();action(()=>game.next());}
function action(fn){const before=game.phase;fn();if(before!==game.phase)render();events();hud();}
function events(){for(const e of game.events.splice(0)){if(e.type==='reward')partyFX.reward(e.key,e.label,e.points);if(e.type==='boss'){cutin('巨大魚、襲来！');sound('boss');}if(e.type==='fever'){cutin('FEVER！ 報酬2倍');sound('catch');}if(e.type==='special'){cutin(game.fever?'MAX サンダー！':'サンダーストライク！');sparkle();sound('special');partyFX.burst('boom','必殺！ 糸の張り回復');}if(e.type==='perfect'){cutin('PERFECT CAST！');sound();}if(e.type==='hit')sound();if(e.type==='awakening'){cutin('ボス覚醒！ 単語で突破');sound('boss');}if(e.type==='boost'){cutin('突破！ 必殺チャージ！');sound('special');}if(e.type==='catch'){coins();cutin(game.fish.id===5?'LEGEND CAUGHT！':'FISH GET！');partyFX.burst('win','★ ＋'+game.catch.points);sound('catch');}if(e.type==='escape')sound('miss');}}
function render(){clearInput();const phase=game.phase;$('targets').hidden=phase!=='select';$('fish').hidden=phase==='select'||phase==='done';$('ocean').className='ocean'+(game.fever?' fever':'')+(game.round===8?' boss':'')+(phase==='reel'?' fighting':'')+(phase==='caught'?' caught':'');$('location').textContent=game.round===8?'GOLDEN ABYSS':game.round<4?'CORAL LAGOON':'MONSTER REEF';
 if(phase==='select'){show('select');$('seaCaption').textContent=game.round===8?'伝説のゴールドファング！':'どの魚を狙う？';$('message').textContent=game.fever?'フィーバー！ この一投の釣果スターが2倍':game.round===8?'最後の一投！ 必殺技を駆使して挑もう':'小物で連続を狙う？ 大物で大量スター？';$('targets').replaceChildren();for(const f of game.targets){const b=document.createElement('button'),art=document.createElement('span'),rank=document.createElement('b'),name=document.createElement('small');b.className='target';art.className='sprite';art.setAttribute('aria-hidden','true');sprite(art,f.id);const factor=game.fever?2:1;rank.textContent=f.rank+' ★'+f.points*factor+'〜'+Math.round(f.points*1.25)*factor;name.textContent=f.name;b.setAttribute('aria-label',f.name+'、'+f.rank+'を狙う');b.append(art,rank,name);b.onclick=()=>action(()=>game.select(f.id));$('targets').append(b);}renderRods();}
 else if(phase==='quiz'){show('quiz');sprite($('fishSprite'),game.fish.id);$('seaCaption').textContent=game.quizKind==='boost'?'覚醒を止めろ！':'単語で魚をヒットさせろ！';$('quizLabel').textContent=game.quizKind==='boost'?'正解で反撃！ チャージ＋1・糸も回復':'正解でヒット ＋ 必殺チャージ1個';$('message').textContent=game.quizKind==='boost'?'時間は停止中。意味を選んでボスを突破！':'焦らず正解しよう。問題中は時間が止まる。';$('word').textContent=game.pair.word;$('choices').replaceChildren();game.options.forEach((p,i)=>{const b=document.createElement('button');b.textContent=p.meaning;b.onclick=()=>action(()=>game.answer(i));$('choices').append(b);});}
 else if(phase==='cast'){show('cast');$('message').textContent='金色ゾーンで止めるとパーフェクト！';$('seaCaption').textContent='タイミングを合わせて投げよう';renderCast();}
 else if(phase==='reel'){show('fight');$('message').textContent='長押しで巻く。暴れたら離す、または必殺技！';renderFight();}
 else if(phase==='correction'){show('correction');$('correctionWord').textContent=game.pair.word+' → '+game.pair.meaning;$('seaCaption').textContent='ゲージ −15%…まだ取り返せる！';$('message').textContent='時間は停止中。意味を確認して続けよう。';}
 else if(phase==='caught'||phase==='escaped')reveal();else if(phase==='done')finish();}
function renderRods(){$('rods').replaceChildren();RODS.forEach((r,i)=>{const b=document.createElement('button');b.textContent=r.name;b.setAttribute('aria-pressed',String(game.rod===i));b.onclick=()=>{if(game.setRod(i))renderRods();};$('rods').append(b);});$('rodDetail').textContent=RODS[game.rod].detail;}
function reveal(){show('reveal');const caught=game.phase==='caught';$('catchKicker').textContent=caught?(game.fish.id===5?'LEGENDARY CATCH!':game.catch.rank+' GET!'):'TRY AGAIN';$('catchTitle').textContent=caught?game.catch.name:'逃げられた…！';$('answerReview').textContent=game.pair.word+' → '+game.pair.meaning;$('next').textContent=game.round===8?'大漁リザルトへ！':'次の魚を狙う！';$('payout').hidden=!caught;if(caught){const f=game.catch,isNew=f.size>(Number(book[f.name])||0);book[f.name]=Math.max(f.size,Number(book[f.name])||0);let saved=true;try{localStorage.setItem('party-fish-book-v1',JSON.stringify(book));}catch{saved=false;}collection();payoutStart=now;payoutTotal=f.points;$('payout').textContent='★ ＋0';$('catchDetail').textContent=`${f.size} cm ／ ランク ${f.grade}`+(isNew?' ／ サイズ新記録！':'')+(game.fever?' ／ FEVER ×2！':'')+(!saved?'（記録は今回のみ）':'');$('seaCaption').textContent=game.fish.id===5?'伝説を釣り上げた！':'大物を釣り上げた！';$('message').textContent=game.feverLeft===2?'次から2投フィーバー！ 釣果スターが2倍':'釣り図鑑に登録！ 次は何を狙う？';}else{$('catchDetail').textContent=game.reason;$('seaCaption').textContent='次の一投でリベンジ！';$('message').textContent='連続記録はリセット。必殺チャージは残る！';}}
function finish(){show('result');$('resultTitle').textContent=game.catches.length+' / 8 匹キャッチ！';$('resultScore').textContent='★ '+game.score;$('resultDetail').textContent='パーフェクト投げ '+game.perfects+'回 ／ ミッション '+game.missions.size+' / 3 達成';const record=game.score>best;best=Math.max(best,game.score);let saved=true;try{localStorage.setItem('party-fish-best-v2',String(best));}catch{saved=false;}$('best').textContent=(record?'NEW RECORD！ ':'')+'自己ベスト ★'+best+(!saved?'（今回は保存できませんでした）':'');$('review').replaceChildren();if(game.misses.length){const h=document.createElement('h3');h.textContent='次の大物のために復習';$('review').append(h);for(const p of new Map(game.misses.map(p=>[p.word,p])).values()){const row=document.createElement('p');row.textContent=p.word+' → '+p.meaning;$('review').append(row);}}$('seaCaption').textContent=game.catches.some(f=>f.id===5)?'伝説ハンター！':'釣果発表！';$('message').textContent='集めたスターと魚図鑑は、次のプレイにも残る。';if(game.score){partyFX.burst('win',record?'自己ベスト更新！':'おつかれさま！');sound('catch');}}
function renderCast(){const power=game.castPower;$('castNeedle').style.left=`calc(${power}% - 2px)`;$('castMeter').setAttribute('aria-valuenow',String(Math.round(power)));}
function renderFight(){$('progress').value=game.progress;$('tension').value=game.tension;$('progressText').textContent=Math.floor(game.progress)+'%';$('tensionText').textContent=Math.floor(game.tension)+'%';$('remaining').textContent=Math.ceil(28-game.elapsed)+'秒';const b=game.behavior,warning=b==='warning'||b==='rush'||game.tension>75;$('behavior').textContent=game.tension>75?'糸が限界！ 離して！':b==='rush'?'あばれてる！ 離す／必殺':b==='warning'?'くるぞ！ 指を離す準備':b==='stunned'?'今がチャンス！ 巻き取れ':'巻くチャンス！';$('fight').classList.toggle('danger',warning);$('ocean').classList.toggle('surge',b==='rush');$('seaCaption').textContent=b==='stunned'?'チャンスタイム！':warning?'離して、いなせ！':'引き寄せろ！';hud();}
const reel=$('reel');reel.addEventListener('pointerdown',e=>{if(!game||game.phase!=='reel'||game.paused||pointer!==null||e.button>0)return;e.preventDefault();pointer=e.pointerId;try{reel.setPointerCapture(pointer);}catch{}game.hold(true);reel.textContent='巻いてる！ 離すとゆるむ';});for(const event of ['pointerup','pointercancel','lostpointercapture'])reel.addEventListener(event,e=>{if(e.pointerId===pointer)clearInput();});reel.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('keydown',e=>{if(!game||game.paused)return;if(e.code==='Space'&&game.phase==='reel'){e.preventDefault();game.hold(true);}if(e.code==='KeyX'&&!e.repeat&&game.phase==='reel'){e.preventDefault();action(()=>game.special());}});window.addEventListener('keyup',e=>{if(e.code==='Space')clearInput();});
$('special').onclick=()=>action(()=>game.special());$('castButton').onclick=()=>action(()=>game.cast());$('acknowledge').onclick=()=>action(()=>game.acknowledge());
function frame(t){const dt=previous?Math.min((t-previous)/1000,.1):0;previous=t;now=t;if(game&&!game.paused){const before=game.phase;game.tick(dt);if(before!==game.phase)render();events();if(game.phase==='reel')renderFight();if(game.phase==='cast')renderCast();if(game.phase==='caught')$('payout').textContent='★ ＋'+Math.round(payoutTotal*Math.min(1,(t-payoutStart)/900));}requestAnimationFrame(frame);}
$('start').onclick=begin;$('again').onclick=begin;$('next').onclick=()=>action(()=>game.next());collection();requestAnimationFrame(frame);
